// Builds src/ds/tokens/_tokens.scss from tokens/tokens.json.
// tokens.json is the single source of truth shared with Figma Variables.
// Run: node scripts/build-tokens.mjs   (no dependencies)
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const t = JSON.parse(readFileSync(join(root, 'tokens/tokens.json'), 'utf8'));
const out = join(root, 'src/ds/tokens/_tokens.scss');

const lines = [
  '// GENERATED by scripts/build-tokens.mjs from tokens/tokens.json. Do not edit by hand.',
  ':root {',
];
for (const [name, def] of Object.entries(t.color)) {
  const hex = t.primitives[def.alias];
  if (!hex) throw new Error(`Unknown primitive "${def.alias}" for ${name}`);
  lines.push(`  ${def.css}: ${hex.toLowerCase()}; // ${name} -> ${def.alias}`);
}
for (const group of ['spacing', 'radius']) {
  for (const [name, def] of Object.entries(t[group])) lines.push(`  ${def.css}: ${def.value}px; // ${name}`);
}
const ff = t.typography['font-family'];
lines.push(`  --ds-font-family: '${ff}', system-ui, sans-serif;`);
for (const [name, def] of Object.entries(t.typography)) {
  if (name === 'font-family') continue;
  const k = name.replace('/', '-');
  lines.push(`  --ds-font-${k}-size: ${def.size}px;`);
  lines.push(`  --ds-font-${k}-line-height: ${def.lineHeight}px;`);
  lines.push(`  --ds-font-${k}-weight: ${def.weight};`);
}
lines.push('}', '');
lines.push('// Sass helper: @include ds-type(body-md);');
lines.push('@mixin ds-type($name) {');
lines.push('  font-family: var(--ds-font-family);');
lines.push('  font-size: var(--ds-font-#{$name}-size);');
lines.push('  line-height: var(--ds-font-#{$name}-line-height);');
lines.push('  font-weight: var(--ds-font-#{$name}-weight);');
lines.push('}', '');

mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, lines.join('\n'));
console.log(`tokens: wrote ${out.replace(root + '/', '')} (${lines.filter(l => l.trim().startsWith('--')).length} custom properties)`);
